      frame_void:      { name: 'Void Tear', category: 'frames', rarity: 'legendary', frameStyle: { border: '3px solid #4a0066', boxShadow: '0 0 18px rgba(74,0,102,0.6), 0 0 6px rgba(168,85,247,0.4)' } },
      frame_ebon:      { name: 'Ebon Crucible', category: 'frames', rarity: 'legendary', frameStyle: { border: '3px solid #c8a860', boxShadow: '0 0 20px rgba(200,168,96,0.7), 0 0 6px rgba(255,215,0,0.4), inset 0 0 4px rgba(200,168,96,0.2)' } },
