      portrait_frost:    { name: 'Frozen Aspect', category: 'portraits', rarity: 'rare', portraitFilter: 'brightness(1.1) saturate(0.4) hue-rotate(180deg)' },
      portrait_infernal: { name: 'Infernal Aspect', category: 'portraits', rarity: 'rare', portraitFilter: 'brightness(1.0) saturate(1.5) hue-rotate(-15deg)' },
      portrait_spectral: { name: 'Spectral Visage', category: 'portraits', rarity: 'epic', portraitFilter: 'brightness(1.3) saturate(0.3) contrast(0.9) opacity(0.85)' },
      portrait_void:     { name: 'Void-Touched', category: 'portraits', rarity: 'epic', portraitFilter: 'brightness(0.8) saturate(1.2) hue-rotate(270deg) contrast(1.2)' },
      portrait_golden:   { name: 'Ascended Form', category: 'portraits', rarity: 'legendary', portraitFilter: 'brightness(1.2) saturate(1.4) sepia(0.3)' },
      // Titles
      title_slayer:      { name: 'Slayer', category: 'titles', rarity: 'common' },
      title_phantom:     { name: 'Phantom', category: 'titles', rarity: 'rare' },
      title_doomcaller:  { name: 'Doomcaller', category: 'titles', rarity: 'epic' },
      title_ebon_lord:   { name: 'Ebon Lord', category: 'titles', rarity: 'legendary' },
      // ── Battle Pass Season 1 Frames ──
      bp_s1_frame_iron:       { name: 'Crucible Iron', category: 'frames', rarity: 'common', frameImage: '/assets/art/frames/bp_s1_frame_iron.png' },
      bp_s1_frame_bloodforge: { name: 'Bloodforge', category: 'frames', rarity: 'rare', frameImage: '/assets/art/frames/bp_s1_frame_bloodforge.png' },
